  iterator begin() { return _M_start; }
  iterator end() { return _M_finish; }
  void _M_insert_aux(iterator, const T&) __asm__("_M_insert_aux__t6vector2Z10debug_textZt12my_allocator1Z10debug_textP10debug_textRC10debug_text");
private:
  Alloc _M_allocator;
  iterator _M_allocate(size_type n) { return n ? _M_allocator.allocate(n) : 0; }
  void _M_deallocate(iterator p, size_type n) { if (p) _M_allocator.deallocate(p, n); }
};

template <class T, class Alloc>
void vector<T, Alloc>::_M_insert_aux(iterator __position, const T& __x) {
  if (_M_finish != _M_end_of_storage) {
    construct(_M_finish, *(_M_finish - 1));
    ++_M_finish;
    T __x_copy = __x;
    copy_backward(__position, _M_finish - 2, _M_finish - 1);
    *__position = __x_copy;
  } else {
    const size_type __old_size = size();
    const size_type __len = __old_size != 0 ? 2 * __old_size : 1;
    iterator __new_start = _M_allocate(__len);
    iterator __new_finish = __new_start;
    __new_finish = uninitialized_copy(_M_start, __position, __new_start);
    construct(__new_finish, __x);
    ++__new_finish;
    __new_finish = uninitialized_copy(__position, _M_finish, __new_finish);
    destroy(begin(), end());
    _M_deallocate(_M_start, _M_end_of_storage - _M_start);
    _M_start = __new_start;
    _M_finish = __new_finish;
    _M_end_of_storage = __new_start + __len;
  }
}

